// src/useAuth.js
import { useState, useEffect, createContext, useContext } from 'react';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [auth, setAuth] = useState(false);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true); // To handle initial loading state

  useEffect(() => {
    // Check for an authentication token in local storage or session storage
    const token = localStorage.getItem('authToken'); // Or sessionStorage.getItem('authToken');

    if (token) {
      // In a real application, you would likely send this token to your backend
      // to verify its validity and retrieve user information.
      // For this basic example, we'll just simulate a logged-in user.
      // Replace this with your actual token validation and user fetching logic.
      const simulatedUser = {
        id: 'someId',
        username: 'testUser',
        role: 'customer' // Or determine the role based on the token or stored user data
      };
      setAuth(true);
      setUser(simulatedUser);
    } else {
      setAuth(false);
      setUser(null);
    }
    setLoading(false); // Authentication check complete
  }, []);

  const login = async (credentials) => {
    setLoading(true);
    // **Replace this with your actual login API call to your backend.**
    // Example using fetch:
    // try {
    //   const response = await fetch('/api/auth/login', {
    //     method: 'POST',
    //     headers: { 'Content-Type': 'application/json' },
    //     body: JSON.stringify(credentials),
    //   });
    //   const data = await response.json();
    //   if (response.ok && data.token && data.user) {
    //     localStorage.setItem('authToken', data.token); // Or sessionStorage.setItem('authToken', data.token);
    //     setUser(data.user);
    //     setAuth(true);
    //     setLoading(false);
    //     return true; // Login successful
    //   } else {
    //     setAuth(false);
    //     setUser(null);
    //     setLoading(false);
    //     return false; // Login failed
    //   }
    // } catch (error) {
    //   console.error('Login error:', error);
    //   setAuth(false);
    //   setUser(null);
    //   setLoading(false);
    //   return false; // Login failed due to error
    // }

    // **Simplified simulation for this example:**
    if (credentials.username === 'restaurant' && credentials.password === 'password') {
      const simulatedRestaurantUser = { id: 'resId', username: 'restaurant', role: 'restaurant' };
      localStorage.setItem('authToken', 'fakeRestaurantToken');
      setUser(simulatedRestaurantUser);
      setAuth(true);
      setLoading(false);
      return true;
    } else if (credentials.username === 'customer' && credentials.password === 'password') {
      const simulatedCustomerUser = { id: 'custId', username: 'customer', role: 'customer' };
      localStorage.setItem('authToken', 'fakeCustomerToken');
      setUser(simulatedCustomerUser);
      setAuth(true);
      setLoading(false);
      return true;
    } else {
      setAuth(false);
      setUser(null);
      setLoading(false);
      return false;
    }
  };

  const logout = () => {
    localStorage.removeItem('authToken'); // Or sessionStorage.removeItem('authToken');
    setAuth(false);
    setUser(null);
  };

  const value = { auth, user, login, logout, loading };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children} {/* Render children only after initial auth check */}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  return useContext(AuthContext);
};
